def minPath(grid, k):
    n = len(grid)
    best = None
    for r in range(n):
        for c in range(n):
            path = _best_path(grid, k, r, c)
            if best is None or path < best:
                best = path
    return best


def _best_path(grid, k, sr, sc):
    n = len(grid)
    # Start at (sr, sc). Greedy: at each step, among all possible next cells
    # (including staying? no - must move to a neighbor each step), pick smallest value.
    # Since paths of length k must move each step, and we want lexicographically smallest,
    # we do DP from the end: best_path_from(cell, steps) = [grid[cell]] + min over neighbors
    # of best_path_from(neighbor, steps-1). Greedy works because comparison is lexicographic
    # starting from cell 0. Actually values all distinct so first cell matters most.

    # Precompute: best sequence starting from each cell of length L, for L = 1.
    # best[L][r][c] = tuple of length L, best path starting at (r,c).
    best = [[[grid[r][c]] for c in range(n)] for r in range(n)]

    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    for length in range(2, k+1):
        new_best = [[None]*n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                cur = None
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n:
                        cand = best[nr][nc]
                        if cur is None or cand < cur:
                            cur = cand
                if cur is None:
                    # no neighbors (n=1 case, but n>=2 so shouldn't happen)
                    new_best[r][c] = [grid[r][c]] + [grid[r][c]]*(length-1)
                else:
                    new_best[r][c] = [grid[r][c]] + cur
        best = new_best

    # Also need length 1 case handled already
    # Find min over all starting cells
    result = None
    for r in range(n):
        for c in range(n):
            if result is None or best[r][c] < result:
                result = best[r][c]
    return result
```
